package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonParser.Feature;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.io.JsonLocation;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

/**
 * Unit tests for MappingIterator.nextValue()
 */
public class MappingIterator_nextValue_TriageGen2Test {

    @Mock
    private JsonParser _parser;

    @Mock
    private Deserializer _deserializer;

    @Mock
    private MappingContext _context;

    private MappingIterator<Object> _iterator;

    // Since MappingIterator is abstract/protected in structure, 
    // we use a concrete implementation for testing the logic provided.
    private static class TestMappingIterator extends MappingIterator<Object> {
        private boolean _hasNextChecked = false;
        private Object _updatedValue = null;
        private JsonParser _parser;
        private Deserializer _deserializer;
        private MappingContext _context;
        private boolean _hasNextValueResult = true;

        public TestMappingIterator(JsonParser parser, Deserializer deserializer, MappingContext context) {
            this._parser = parser;
            this._deserializer = deserializer;
            this._context = context;
        }

        public void setHasNextChecked(boolean val) { this._hasNextChecked = val; }
        public void setHasNextValue(boolean val) { this._hasNextValueResult = val; }
        public void setParser(JsonParser parser) { this._parser = parser; }
        public void setUpdatedValue(Object val) { this._updatedValue = val; }

        @Override
        public boolean hasNextValue() throws IOException {
            return _hasNextValueResult;
        }

        @Override
        protected Object _throwNoSuchElement() {
            throw new java.util.NoSuchElementException("No such element");
        }

        @Override
        public void close() throws IOException {}

        // Expose protected fields for the test logic simulation if needed, 
        // but here we rely on the provided method body logic.
    }

    // Mocking the Deserializer interface used in the method
    interface Deserializer {
        Object deserialize(JsonParser p, MappingContext c) throws IOException;
        void deserialize(JsonParser p, MappingContext c, Object value) throws IOException;
    }

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testNextValue_NoHasNextChecked_NoHasNextValue() throws IOException {
        TestMappingIterator iter = new TestMappingIterator(_parser, _deserializer, _context);
        iter.setHasNextChecked(false);
        iter.setHasNextValue(false);

        try {
            iter.nextValue();
        } catch (java.util.NoSuchElementException e) {
            // Expected
        }
    }

    @Test
    public void testNextValue_NoHasNextChecked_HasNextValue_ParserNull() throws IOException {
        TestMappingIterator iter = new TestMappingIterator(null, _deserializer, _context);
        iter.setHasNextChecked(false);
        iter.setHasNextValue(true);

        try {
            iter.nextValue();
        } catch (java.util.NoSuchElementException e) {
            // Expected
        }
    }

    @Test
    public void testNextValue_HasNextChecked_ParserNull() throws IOException {
        TestMappingIterator iter = new TestMappingIterator(null, _deserializer, _context);
        iter.setHasNextChecked(true);

        try {
            iter.nextValue();
        } catch (java.util.NoSuchElementException e) {
            // Expected
        }
    }

    @Test
    public void testNextValue_StandardPath_NoUpdatedValue() throws IOException {
        Object expectedValue = new Object();
        TestMappingIterator iter = new TestMappingIterator(_parser, _deserializer, _context);
        iter.setHasNextChecked(false);
        iter.setHasNextValue(true);

        when(_deserializer.deserialize(_parser, _context)).thenReturn(expectedValue);

        Object result = iter.nextValue();

        assertEquals(expectedValue, result);
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_StandardPath_WithUpdatedValue() throws IOException {
        Object expectedValue = new Object();
        TestMappingIterator iter = new TestMappingIterator(_parser, _deserializer, _context);
        iter.setHasNextChecked(false);
        iter.setHasNextValue(true);
        iter.setUpdatedValue(expectedValue);

        doNothing().when(_deserializer).deserialize(_parser, _context, expectedValue);

        Object result = iter.nextValue();

        assertEquals(expectedValue, result);
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_ExceptionInDeserialize_ClearsToken() throws IOException {
        TestMappingIterator iter = new TestMappingIterator(_parser, _deserializer, _context);
        iter.setHasNextChecked(false);
        iter.setHasNextValue(true);

        when(_deserializer.deserialize(_parser, _context)).thenThrow(new IOException("Simulated IO Error"));

        try {
            iter.nextValue();
        } catch (IOException e) {
            assertEquals("Simulated IO Error", e.getMessage());
        }

        // Ensure finally block executed
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_ExceptionInDeserializeWithUpdatedValue_ClearsToken() throws IOException {
        Object updatedValue = new Object();
        TestMappingIterator iter = new TestMappingIterator(_parser, _deserializer, _context);
        iter.setHasNextChecked(false);
        iter.setHasNextValue(true);
        iter.setUpdatedValue(updatedValue);

        doThrow(new IOException("Simulated IO Error")).when(_deserializer).deserialize(_parser, _context, updatedValue);

        try {
            iter.nextValue();
        } catch (IOException e) {
            assertEquals("Simulated IO Error", e.getMessage());
        }

        // Ensure finally block executed
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_ResetsHasNextChecked() throws IOException {
        TestMappingIterator iter = new TestMappingIterator(_parser, _deserializer, _context);
        iter.setHasNextChecked(true);
        iter.setHasNextValue(true);

        when(_deserializer.deserialize(_parser, _context)).thenReturn(new Object());

        iter.nextValue();

        // The code sets _hasNextChecked = false;
        // We check this by making sure the next call triggers hasNextValue()
        iter.setHasNextValue(false);
        try {
            iter.nextValue();
        } catch (java.util.NoSuchElementException e) {
            // Success: it checked hasNextValue again because _hasNextChecked was reset to false
        }
    }
}
